def split_row(line: str):
    """Split one CSV line into fields.

    Commas inside double-quoted fields are part of the field, and a pair of
    double quotes inside such a field represents one literal double quote.
    """
    fields = []
    field = []
    in_quotes = False

    i = 0
    while i < len(line):
        char = line[i]

        if in_quotes:
            if char == '"':
                if i + 1 < len(line) and line[i + 1] == '"':
                    field.append('"')
                    i += 1
                else:
                    in_quotes = False
            else:
                field.append(char)
        elif char == ',' :
            fields.append(''.join(field))
            field = []
        elif char == '"' and not field:
            in_quotes = True
        else:
            field.append(char)

        i += 1

    fields.append(''.join(field))
    return fields

